<section class="gauntlet-record-section" aria-label="A published Gauntlet round">
  <div class="gr-wrap">

    <p class="gr-eyebrow">The Gauntlet &middot; public record</p>

    <!-- The state box carries every non-success outcome and is the ONLY thing
         rendered until a real response arrives. It starts as "loading" rather
         than as an error, because an error before the fetch has returned would
         be a claim we have not earned. -->
    <div class="gr-state" data-gr-state>
      <h2 data-gr-state-head>Fetching this round&hellip;</h2>
      <p data-gr-state-body>One moment.</p>
      <a class="gr-cta" href="/tools/gauntlet/index.html" hidden data-gr-state-cta>Argue your own round</a>
    </div>

    <article hidden data-gr-round>
      <p class="gr-dates" data-gr-dates></p>
      <h1 class="gr-headline" data-gr-headline></h1>
      <p class="gr-body" data-gr-provocation></p>

      <div class="gr-move is-mine">
        <p class="gr-label">The position filed</p>
        <p class="gr-text" data-gr-position></p>
      </div>

      <div class="gr-move is-theirs">
        <p class="gr-label">Vonc answered</p>
        <p class="gr-text" data-gr-counter></p>
      </div>

      <div class="gr-move is-theirs">
        <p class="gr-label">And challenged</p>
        <p class="gr-text" data-gr-challenge></p>
      </div>

      <div class="gr-move is-mine">
        <p class="gr-label">The defence</p>
        <p class="gr-text" data-gr-defence></p>
      </div>

      <div class="gr-ruling">
        <p class="gr-ruling-line" data-gr-verdict></p>
        <p class="gr-ruling-why" data-gr-reasons></p>
      </div>

      <div class="gr-foot">
        <p>
          This is one round of The Gauntlet, published by the person who argued
          it when they shared their card. Nobody is named and no account exists:
          the record keeps the argument, not the arguer.
        </p>
        <a class="gr-cta" href="/tools/gauntlet/index.html">Argue your own round</a>
      </div>
    </article>

  </div>
</section>

<script>
  (function () {
    "use strict";

    var API = "https://tools.apis.uk";

    // Mirrors store.ValidSlug / SlugAlphabet / SlugLength in the island engine
    // (internal/tools-api/store/rounds.go). Kept here so a malformed address
    // never becomes a request, and so the page's own "no such record" copy is
    // reached without a round trip. The server still validates: this is a
    // courtesy, not the boundary.
    var SLUG_ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789_";
    var SLUG_LENGTH = 10;

    function validSlug(s) {
      if (typeof s !== "string" || s.length !== SLUG_LENGTH) return false;
      for (var i = 0; i < s.length; i++) {
        if (SLUG_ALPHABET.indexOf(s.charAt(i)) === -1) return false;
      }
      return true;
    }

    var section = document.querySelector(".gauntlet-record-section");
    if (!section) return;

    var el = {
      state: section.querySelector("[data-gr-state]"),
      stateHead: section.querySelector("[data-gr-state-head]"),
      stateBody: section.querySelector("[data-gr-state-body]"),
      stateCta: section.querySelector("[data-gr-state-cta]"),
      round: section.querySelector("[data-gr-round]"),
      dates: section.querySelector("[data-gr-dates]"),
      headline: section.querySelector("[data-gr-headline]"),
      provocation: section.querySelector("[data-gr-provocation]"),
      position: section.querySelector("[data-gr-position]"),
      counter: section.querySelector("[data-gr-counter]"),
      challenge: section.querySelector("[data-gr-challenge]"),
      defence: section.querySelector("[data-gr-defence]"),
      verdict: section.querySelector("[data-gr-verdict]"),
      reasons: section.querySelector("[data-gr-reasons]")
    };

    // EVERY field on this page is written with textContent, with no exception
    // and no allowlist. Two of them (position, defence) are prose typed by a
    // member of the public and then served to every other visitor, so the page
    // has exactly one rule about untrusted text, and the rule is auditable by
    // grep: the markup-assigning DOM properties must not appear in this file at
    // all. verify_round_record.py asserts a count of zero for each of them.
    function put(node, value) {
      if (node) node.textContent = value == null ? "" : String(value);
    }

    // The provocation's headline carries inline markup (<em>) because it is
    // rendered as HTML on the arena page. Here it is stripped rather than
    // allowed, so the record and the share card show the same string — the
    // card does the same thing (buildVerdictCard in gauntlet-interface.js).
    function plain(value) {
      return value == null ? "" : String(value).replace(/<[^>]*>/g, "").trim();
    }

    function showState(head, body, offerCta) {
      put(el.stateHead, head);
      put(el.stateBody, body);
      if (el.stateCta) el.stateCta.hidden = !offerCta;
      if (el.state) el.state.hidden = false;
      if (el.round) el.round.hidden = true;
    }

    function fmtDate(iso) {
      if (!iso) return "";
      var d = new Date(iso);
      if (isNaN(d.getTime())) return "";
      return d.toLocaleDateString("en-GB", {
        day: "numeric", month: "long", year: "numeric"
      });
    }

    function render(r) {
      var prov = r.provocation || {};
      var counter = r.counter || {};
      var verdict = r.verdict || {};

      // Only headline and body are taken from the provocation. It also carries
      // `stats` (an array), `primary_cta` and `secondary_cta` — marketing
      // furniture for the arena page. `stats` in particular would put numbers
      // on a record page, and a number this page did not compute is exactly
      // what the honesty rail forbids.
      put(el.headline, plain(prov.headline));
      put(el.provocation, plain(prov.body));

      put(el.position, r.position);
      put(el.counter, counter.counter_position);
      put(el.challenge, counter.challenge);
      put(el.defence, r.defence);

      var ruling = plain(verdict.verdict);
      put(el.verdict, ruling ? "The judge ruled: " + ruling + "." : "The judge ruled.");
      put(el.reasons, verdict.reasons);

      var argued = fmtDate(r.argued_at);
      var published = fmtDate(r.published_at);
      var line = "";
      if (argued) line = "Argued " + argued;
      if (published && published !== argued) {
        line = line ? line + " · published " + published : "Published " + published;
      }
      put(el.dates, line);

      if (el.state) el.state.hidden = true;
      if (el.round) el.round.hidden = false;
    }

    function slugFromLocation() {
      var m = /[?&]r=([^&#]*)/.exec(window.location.search);
      if (!m) return "";
      try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
    }

    var slug = slugFromLocation();

    if (!slug) {
      showState(
        "This page shows one published round",
        "It needs the address of a round to show. If you followed a link here, " +
        "the address may have been cut short somewhere along the way.",
        true
      );
      return;
    }

    if (!validSlug(slug)) {
      showState(
        "That is not a round address",
        "The address in the link is not the right shape, so there is nothing to " +
        "look up. Nothing was found or lost — the link is simply wrong.",
        true
      );
      return;
    }

    fetch(API + "/api/v1/tools/gauntlet/round/" + encodeURIComponent(slug), {
      method: "GET",
      headers: { Accept: "application/json" }
    })
      .then(function (res) {
        if (res.status === 404) {
          var e404 = new Error("not found");
          e404.status = 404;
          throw e404;
        }
        if (!res.ok) {
          var err = new Error("HTTP " + res.status);
          err.status = res.status;
          throw err;
        }
        return res.json();
      })
      .then(render)
      .catch(function (err) {
        // 404 is returned for a round that was never published and for one that
        // does not exist, identically and on purpose — the page cannot tell
        // them apart, so it does not pretend to.
        if (err && err.status === 404) {
          showState(
            "No public record at that address",
            "Either nothing was ever published here, or whoever published it has " +
            "since taken it down.",
            true
          );
          return;
        }
        if (err && err.status === 429) {
          showState(
            "Too many requests just now",
            "The record service is rate limited and has asked us to wait. Give it " +
            "a minute and reload — the round is still there.",
            false
          );
          return;
        }
        showState(
          "Could not reach the record",
          "The round may well exist; we could not fetch it just now. Reloading " +
          "in a moment is worth a try.",
          false
        );
      });
  })();
</script>
